+(() => {
+  const dialog = document.getElementById('confirm-dialog');
+  const trigger = document.querySelector('.trigger');
+  const cancelBtn = dialog.querySelector('[data-close]');
+  const confirmBtn = dialog.querySelector('[data-confirm]');
+  const status = document.getElementById('status');
+
+  trigger.addEventListener('click', () => {
+    if (typeof dialog.showModal === 'function') {
+      dialog.showModal();
+      // Focus the safe (Cancel) action, not the destructive one
+      requestAnimationFrame(() => cancelBtn.focus());
+    }
+  });
+
+  cancelBtn.addEventListener('click', () => dialog.close('cancel'));
+
+  confirmBtn.addEventListener('click', () => dialog.close('delete'));
+
+  dialog.addEventListener('close', () => {
+    if (dialog.returnValue === 'delete') {
+      status.textContent = 'Image deleted from your library.';
+    }
+  });
+
+  // Click outside (on backdrop) closes the dialog
+  dialog.addEventListener('click', (event) => {
+    if (event.target === dialog) {
+      dialog.close('cancel');
+    }
+  });
+})();
+
")

