const path = require('path');
const { JSDOM } = require('jsdom');
const axe = require('axe-core');

const html = fs.readFileSync(path.resolve(__dirname, 'index.html'), 'utf8');

async function audit(label, mutate) {
  const dom = new JSDOM(html, { runScripts: 'dangerously', resources: 'usable', pretendToBeVisual: true });
  await new Promise(r => dom.window.addEventListener('load', r));
  // Inject axe
  dom.window.eval(axe.source);
  if (mutate) mutate(dom.window);
  const results = await dom.window.axe.run(dom.window.document, {
    runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice'] }
  });
  console.log(`\n=== ${label} ===`);
  console.log('violations:', results.violations.length);
  for (const v of results.violations) {
    console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
    for (const n of v.nodes) {
      console.log('   target:', n.target.join(' '));
      console.log('   summary:', (n.failureSummary || '').replace(/\n/g, ' | '));
    }
  }
  dom.window.close();
}

(async () => {
  await audit('CLOSED');
  await audit('OPEN', (win) => {
    const dlg = win.document.getElementById('confirm-dialog');
    // jsdom may not implement showModal; force open attribute
