<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Image preview — Mountain sunrise</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0e1117;
      --surface: #161b22;
      --surface-2: #21262d;
      --border: #30363d;
      --text: #e6edf3;
      --text-muted: #b8c0ca;
      --accent: #2f81f7;
      --danger: #da3633;
      --danger-hover: #f85149;
      --focus: #79c0ff;
      --shadow: 0 16px 48px rgba(0, 0, 0, 0.6);
    }

    * { box-sizing: border-box; }

    html, body {
      margin: 0;
      padding: 0;
      background: var(--bg);
      color: var(--text);
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
      line-height: 1.5;
    }

    .skip-link {
      position: absolute;
      top: -100px;
      left: 8px;
      background: var(--accent);
      color: #fff;
      padding: 8px 12px;
      border-radius: 6px;
      text-decoration: none;
      z-index: 100;
    }
    .skip-link:focus { top: 8px; }

    .page-header {
      border-bottom: 1px solid var(--border);
      padding: 16px 24px;
    }
    .page-header h1 {
      font-size: 1.125rem;
      margin: 0;
      font-weight: 600;
    }

    main {
      max-width: 720px;
      margin: 0 auto;
      padding: 32px 24px 64px;
    }

    .preview {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      overflow: hidden;
      box-shadow: var(--shadow);
    }

    .preview-image {
      display: block;
      width: 100%;
      height: auto;
      aspect-ratio: 16 / 10;
      object-fit: cover;
      background: var(--surface-2);
    }

    .preview-meta {
      padding: 16px 20px;
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      align-items: center;
      justify-content: space-between;
      border-top: 1px solid var(--border);
    }

    .preview-title { margin: 0; font-size: 1rem; font-weight: 600; }
    .preview-sub { margin: 2px 0 0; font-size: 0.875rem; color: var(--text-muted); }

    .actions { display: flex; gap: 8px; flex-wrap: wrap; }

    .btn {
      font: inherit;
      cursor: pointer;
      border-radius: 6px;
      padding: 8px 16px;
      border: 1px solid var(--border);
      background: var(--surface-2);
      color: var(--text);
      min-height: 36px;
      transition: background 0.15s, border-color 0.15s;
    }
    .btn:hover { background: #2d333b; }
    .btn:focus-visible {
      outline: 2px solid var(--focus);
      outline-offset: 2px;
    }

    .btn-danger {
      background: transparent;
      color: var(--danger-hover);
      border-color: var(--border);
    }
    .btn-danger:hover {
      background: rgba(248, 81, 73, 0.12);
      border-color: var(--danger);
    }

    .btn-danger-solid {
      background: var(--danger);
      border-color: var(--danger);
      color: #fff;
    }
    .btn-danger-solid:hover {
      background: var(--danger-hover);
      border-color: var(--danger-hover);
    }

    .visually-hidden {
      position: absolute;
      width: 1px; height: 1px;
      padding: 0; margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .dialog {
      padding: 0;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: var(--surface);
      color: var(--text);
      max-width: min(440px, calc(100vw - 32px));
      width: 100%;
      box-shadow: var(--shadow);
    }

    .dialog::backdrop {
      background: rgba(0, 0, 0, 0.65);
      backdrop-filter: blur(2px);
    }

    .dialog-body { padding: 24px 24px 16px; }

    .dialog-title { margin: 0 0 8px; font-size: 1.125rem; font-weight: 600; }

    .dialog-desc { margin: 0; color: var(--text-muted); font-size: 0.9375rem; }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 8px;
      padding: 16px 24px 20px;
      border-top: 1px solid var(--border);
      background: var(--surface-2);
      border-radius: 0 0 12px 12px;
      flex-wrap: wrap;
    }

    @media (max-width: 380px) {
      .dialog-actions { flex-direction: column-reverse; }
      .dialog-actions .btn { width: 100%; }
    }

    @media (prefers-reduced-motion: no-preference) {
      .dialog[open] { animation: dialog-in 0.15s ease-out; }
    }
    @keyframes dialog-in {
      from { opacity: 0; transform: translateY(-4px) scale(0.98); }
      to { opacity: 1; transform: none; }
    }

    @media (forced-colors: active) {
      .dialog, .btn { border: 1px solid CanvasText; }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <header class="page-header">
    <h1>Library</h1>
  </header>

  <main id="main">
    <article class="preview" aria-labelledby="image-title">
      <img
        class="preview-image"
        src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&amp;fit=crop&amp;w=1200&amp;q=70"
        alt="Mountain range at sunrise with mist drifting through the valleys."
      >
      <div class="preview-meta">
        <div>
          <h2 id="image-title" class="preview-title">Mountain sunrise</h2>
          <p class="preview-sub">Uploaded May 2, 2026 · 2.4 MB</p>
        </div>
        <div class="actions">
          <button type="button" class="btn">Download</button>
          <button type="button" class="btn btn-danger trigger" aria-haspopup="dialog" aria-controls="confirm-dialog">
            Delete
          </button>
        </div>
      </div>
    </article>

    <p id="status" role="status" aria-live="polite" class="visually-hidden"></p>
  </main>

  <dialog id="confirm-dialog" class="dialog"
          aria-labelledby="confirm-title"
          aria-describedby="confirm-desc">
    <div class="dialog-body">
      <h2 id="confirm-title" class="dialog-title">Delete this image?</h2>
      <p id="confirm-desc" class="dialog-desc">
        &ldquo;Mountain sunrise&rdquo; will be permanently removed from your library. This action can&rsquo;t be undone.
      </p>
    </div>
    <div class="dialog-actions">
      <button type="button" class="btn" data-close>Cancel</button>
      <button type="button" class="btn btn-danger-solid" data-confirm>Delete image</button>
    </div>
  </dialog>

  <script>
    (() => {
      const dialog = document.getElementById('confirm-dialog');
      const trigger = document.querySelector('.trigger');
      const cancelBtn = dialog.querySelector('[data-close]');
      const confirmBtn = dialog.querySelector('[data-confirm]');
      const status = document.getElementById('status');

      trigger.addEventListener('click', () => {
        if (typeof dialog.showModal === 'function') {
          dialog.showModal();
          requestAnimationFrame(() => cancelBtn.focus());
        }
      });

      cancelBtn.addEventListener('click', () => dialog.close('cancel'));
      confirmBtn.addEventListener('click', () => dialog.close('delete'));

      dialog.addEventListener('close', () => {
        if (dialog.returnValue === 'delete') {
          status.textContent = 'Image deleted from your library.';
        }
      });

      dialog.addEventListener('click', (event) => {
        if (event.target === dialog) {
          dialog.close('cancel');
        }
      });
    })();
  </script>
</body>
</html>
